using System.Numerics;
using System.Reflection;
using System.Security.Cryptography;
using ByteEngine.Core;
using ByteEngine.Core.Graphics;
using ByteEngine.Core.InputSystem;
using ByteEngine.Core.Scene;
using KarlsonDemo.Plugin;
internal static class MiningCompanySystemsCheck
{
 static void Check(bool value,string message){if(!value)throw new Exception(message);Console.WriteLine("PASS COMPANY "+message);}
 public static void Run(Scene scene,MiningOperation3D op)
 {
  var file=Program.Root+"/Scenes/Main.bytescene";var hash=SHA256.HashData(File.ReadAllBytes(file));var ui=scene.GameObjects.SelectMany(o=>o.Components.OfType<MiningBusinessUi3D>()).Single();var trade=op.GameObject.GetComponent<MiningTrade3D>()!;
  var host=new SceneManager();host.LoadScene(scene);var player=scene.FindGameObject(op.PlayerObjectId)!;player.Transform.WorldPosition=scene.FindGameObject(ui.TerminalObjectId)!.Transform.WorldPosition+new Vector3(0,0,-1);
  void Set(string n,object v)=>typeof(MiningOperation3D).GetProperty(n)!.SetValue(op,v);
  void Frame(Vector2? point=null,bool down=false,float wheel=0,bool right=false){var raw=new RawInputSnapshot{MouseWheel=wheel};if(right)raw.MouseButtonsDown.Add(MouseButton.Right);if(down)raw.MouseButtonsDown.Add(MouseButton.Left);typeof(Input).GetMethod("UpdatePortable",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[raw,true]);Input.SetGameViewPointer((point??new(640,360))/new Vector2(1280,720),new(1280,720),true);typeof(Time).GetMethod("Update",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[.05d]);typeof(Scene).GetMethod("UpdateInternal",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(scene,null);}
  void Tap(float x,float y){float left=ui.Screen==MiningScreen.Research?312:692;Frame();Frame(new(left+x,30+y),true);Frame();}
  UiWidget Widget(Guid id)=>scene.FindGameObject(id)!.GetComponent<UiWidget>()!;
  void Click(Guid id){Frame();var widget=Widget(id);Check(widget.Visible,"requested control is visible");var r=UiLayout.Resolve(widget.GameObject,widget.Anchor,widget.Offset,widget.Size,new(1280,720));Frame(r.Position+r.Size/2,true);Frame();}
  Frame();Set("Credits",10000);Set("CompletedRounds",2);Set("RawOre",40);Set("RefinedOre",80);trade.Initialize();ui.Open(MiningScreen.Company);Frame();Check(ui.Screen==MiningScreen.Company,"terminal opens Trade landing page");Tap(260,210);Check(ui.Screen==MiningScreen.Market&&ui.GuaranteedSelected,"delivery card opens real contracts");Click(ui.Contract0ButtonObjectId);Check(trade.ActiveDeliveryContract==null,"selection previews an order without accepting it");Click(ui.PrimaryButtonObjectId);Check(trade.ActiveDeliveryContract!=null,"Accept snapshots the selected contract");int stock=op.RefinedOre,credits=op.Credits;Click(ui.PrimaryButtonObjectId);Check(trade.SaleInProgress&&!Widget(ui.PrimaryButtonObjectId).Interactable,"Deliver starts shipment and prevents repeat purchase");trade.Tick(trade.SaleSeconds+1);Frame();Check(op.RefinedOre<stock&&op.Credits>credits,"delivery consumes ore and pays real credits");
  Tap(100,98);Check(ui.Screen==MiningScreen.Company,"Trade tab returns to landing page");Tap(250,390);Check(ui.Screen==MiningScreen.Market&&!ui.GuaranteedSelected,"exchange card opens live prices");Click(ui.RawButtonObjectId);Check(!ui.RefinedSelected,"Raw tab changes resource");Click(ui.RefinedButtonObjectId);Check(ui.RefinedSelected,"Refined tab changes resource");Tap(424,456);Check(ui.BuyingOre,"Buy segment selects buying");Tap(424,456);Check(ui.BuyingOre,"selected Buy segment does not toggle to Sell");ui.SetQuantity(1);credits=op.Credits;stock=op.RefinedOre;int preview=(int)typeof(MiningBusinessUi3D).GetMethod("CompanyMarketTotal",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(ui,[trade])!;Click(ui.PrimaryButtonObjectId);Check(credits-op.Credits==preview&&op.RefinedOre==stock+1,"Buy uses current quote and real inventory");Tap(496,456);Check(!ui.BuyingOre,"Sell segment selects selling");
  Tap(280,98);Check(ui.Screen==MiningScreen.Research,"Research tab opens graph and account sidebar");float zoom=ui.ResearchZoom;Frame(new(562,310),wheel:1);Check(ui.ResearchZoom>zoom,"graph wheel zoom remains functional");var pan=ui.ResearchPan;Frame(new(562,310),right:true);Frame(new(586,322),right:true);Frame();Check(ui.ResearchPan!=pan,"RMB pans graph while the terminal owns the pointer");var node=trade.Research.First(n=>trade.CanBuyResearch(n.Id));int index=trade.Research.ToList().FindIndex(n=>n.Id==node.Id),rank=trade.ResearchRank(node.Id);Click(ui.ResearchButtonObjectIds[index]);Click(ui.PrimaryButtonObjectId);Check(trade.ResearchRank(node.Id)==rank+1,"graph selection and Unlock buy actual research");Tap(638+12+254*.6f,390);Check(op.CompanyDepositPercent==60,"Research account sidebar slider changes saved split");Tap(448,98);Check(ui.Screen==MiningScreen.Account,"Account tab opens detailed account");Tap(40+480*.4f,358);Check(op.CompanyDepositPercent==40,"Account slider matches visible track");int capacity=op.CargoCapacity;Tap(250,540);Check(op.CargoCapacity>capacity,"cargo button retains real capacity upgrade");Click(ui.CloseXButtonObjectId);Check(ui.Screen==MiningScreen.None&&!Input.IsUiPointerRequested,"X closes terminal and returns gameplay pointer");host.UnloadScene();Check(hash.SequenceEqual(SHA256.HashData(File.ReadAllBytes(file))),"company checks preserve scene and player saves");
 }
}
